import React from 'react';import {Routes,Route,useLocation} from 'react-router-dom';import {AnimatePresence,motion} from 'framer-motion';import Layout from './components/Layout';import Home from './pages/Home';import Projects from './pages/Projects';import ProjectDetail from './pages/ProjectDetail';import Expertise from './pages/Expertise';import Studio from './pages/Studio';import Contact from './pages/Contact';import {Legal,Privacy} from './pages/Legal';import './styles.css';
function AnimatedRoutes(){const location=useLocation();return <AnimatePresence mode="wait"><motion.div key={location.pathname} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} transition={{duration:.22}}><Routes location={location}><Route path="/" element={<Home/>}/><Route path="/projets" element={<Projects/>}/><Route path="/projets/:slug" element={<ProjectDetail/>}/><Route path="/expertise" element={<Expertise/>}/><Route path="/studio" element={<Studio/>}/><Route path="/contact" element={<Contact/>}/><Route path="/mentions-legales" element={<Legal/>}/><Route path="/confidentialite" element={<Privacy/>}/><Route path="*" element={<Home/>}/></Routes></motion.div></AnimatePresence>}
export default function App(){return <Layout><AnimatedRoutes/></Layout>}
